CREATE OR REPLACE FUNCTION public.enforce_product_limit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
    v_max   int;
    v_count int;
begin
    -- is_active=false로 등록되는 상품(있다면)은 애초에 슬롯을 안 쓰므로 검사 불필요
    if coalesce(new.is_active, true) = false then
        return new;
    end if;

    select sp.max_products into v_max
    from center_subscriptions cs join subscription_plans sp on sp.id = cs.plan_id
    where cs.center_id = new.center_id;

    if v_max is null then
        return new;
    end if;

    select count(*) into v_count from products where center_id = new.center_id and is_active;
    if v_count >= v_max then
        raise exception '현재 플랜은 상품을 최대 %종까지만 등록할 수 있어요. 플랜을 업그레이드해주세요.', v_max;
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_center_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    -- 서버 작업:
    -- service_role JWT 또는 SQL Editor/cron처럼 요청 JWT가 없는 DB 내부 작업.
    -- anon JWT는 trusted 경로에서 제외한다.
    if auth.uid() is null
       and coalesce(auth.jwt() ->> 'role', '') <> 'anon' then
        return new;
    end if;

    -- 플랫폼 운영자는 기존 동작 유지
    if public.is_platform_admin() then
        return new;
    end if;

    -- 일반 로그인 사용자는 승인 상태/내부 QA 여부를 직접 정할 수 없다
    new.status := 'pending';
    new.is_internal := false;

    return new;
end;
$function$
